// The fixture layer (SPEC-platform §10; M11 plan decision 8): 12 boxes of three
// kinds, generated by `generate.ts` (no Blender). It proves that a layer added
// only to a registry reaches the Layers panel, its system group, the URL, the
// loader, the batches and picking. Never shipped: only the test registry
// (`../../registry.ts`) lists it.
import { defineLayer } from "../../../../../src/systems/types";

export const widgets = defineLayer({
  id: "widgets",
  system: "demo",
  code: "w",
  label: "Widgets",
  ghostOrder: 4,
  // Chosen to clear M10's colour-vision table (re-run by tests/fixture.test.ts): ΔE2000 ≥ 9.9 from every colour it meets under all three visions, 3:1 on the legend, label text 4.5:1 over it.
  colour: { material: "#dd2200", debug: "#dd2200" },
  models: {
    file: "widgets",
    eager: false,
    chunking: "single",
    debugManifest: () => import("./models/manifest.json"),
    budgets: { high: { maxMiB: 0.1, targetTris: 144 }, low: { maxMiB: 0.1, targetTris: 144 } },
  },
  defaultSetting: "off",
  kinds: [
    { id: "gear", noun: { one: "gear", many: "gears" }, labelPriority: 7 },
    { id: "spring", noun: { one: "spring", many: "springs" }, labelPriority: 8 },
    { id: "lever", noun: { one: "lever", many: "levers" }, labelPriority: 9 },
  ],
});

/** The 12 structures: four of each kind, `widget_<kind>_<n>`. */
export const WIDGET_IDS: readonly string[] = widgets.kinds.flatMap((k) => [1, 2, 3, 4].map((n) => `widget_${k.id}_${n}`));
